use super::*;
use crate::filesystem::identity::FilesystemIdentity;
fn dir(path:&str)->DirectoryBinding {DirectoryBinding {path:NativePath::from_path(Path::new(path)),identity:FilesystemIdentity {platform:"linux".into(),filesystem_id:"1".into(),file_id:"1".into(),link_count:None},mode:0o40700,uid:1000,gid:1000}}
fn file(path:&str,n:u64)->FileBinding {FileBinding {directory:dir("/media"),path:NativePath::from_path(Path::new(path)),identity:FilesystemIdentity {platform:"linux".into(),filesystem_id:"1".into(),file_id:n.to_string(),link_count:Some(1)},size_bytes:n,modified_unix_ns:0,changed_unix_ns:0,mode:0o100600,uid:1000,gid:1000,blake3:"a".repeat(64)}}
fn review()->StagedVideoReview {let mut r=StagedVideoReview {schema:"optiflow.staged-video-replacement-review.v1".into(),fingerprint:String::new(),operation:"stage_video_replacement.v1".into(),artifact_schema:"optiflow.video-candidate-artifact-set.v2".into(),source:file("/media/a.mkv",100),candidate:file("/state/set/candidate.mkv",80),candidate_set:NativePath::from_path(Path::new("/state/set")),marker_blake3:"a".repeat(64),evidence_blake3:"b".repeat(64),policy_fingerprint:"c".repeat(64),state:dir("/state"),retention:dir("/retained"),encoded_logical_reduction_bytes:20,current_source_content_bound:true,independent_container_comparison:true,live_decode_observed:false,native_properties_preserved:false,replacement_qualified:false,apply_authority:false,original_disposal_authority:false};r.fingerprint=hash(&r).unwrap();r}
#[test] fn current_stream_copy_bytes_do_not_create_live_decode_or_disposal_authority(){let r=review();r.validate().unwrap();assert!(admit_to_transaction(&r).is_err());for field in ["live_decode_observed","native_properties_preserved","apply_authority","original_disposal_authority"] {let mut raw=serde_json::to_value(&r).unwrap();raw[field]=serde_json::json!(true);assert!(StagedVideoReview::from_json_slice(&serde_json::to_vec(&raw).unwrap()).is_err());}}
#[test] fn video_review_cannot_be_loaded_as_a_png_replacement_plan(){let r=review();assert!(super::super::replacement::ReplacementPlan::from_json_slice(&serde_json::to_vec(&r).unwrap()).is_err());}
#[test] fn unknown_artifact_profile_does_not_upgrade_staged_review(){let mut r=review();r.artifact_schema="optiflow.video-candidate-artifact-set.v3".into();r.fingerprint.clear();r.fingerprint=hash(&r).unwrap();assert!(r.validate().is_err());}
#[test] fn changed_retention_volume_invalidates_video_review(){let mut r=review();r.retention.identity.filesystem_id="2".into();r.fingerprint.clear();r.fingerprint=hash(&r).unwrap();assert!(r.validate().is_err());}
